import pandas as pd
df = pd.read_excel('inputs/pone.0150501.s002.xls')
# Check all rows in the first column for non-miRNA entries
for i, val in enumerate(df.iloc[:, 0]):
    if pd.notna(val):
        s = str(val)
        if not s.startswith('hsa-'):
            print(f'Row {i}: {repr(val)}')
